SET NOCOUNT ON;
SELECT CASE WHEN MAX(b.backup_finish_date) IS NULL OR DATEDIFF(hour, MAX(b.backup_finish_date), GETDATE()) >= 336 THEN 'Critical' WHEN DATEDIFF(hour, MAX(b.backup_finish_date), GETDATE()) >= 168 THEN 'Warning' ELSE 'Healthy' END AS __OPSBOX_STATUS,
  d.name AS databaseName, ISNULL(CONVERT(varchar(19), MAX(b.backup_finish_date), 120), 'NONE') AS lastFullBackup, ISNULL(DATEDIFF(hour, MAX(b.backup_finish_date), GETDATE()), -1) AS backupAgeHours
FROM sys.databases d LEFT JOIN msdb.dbo.backupset b ON b.database_name = d.name AND b.type = 'D'
WHERE d.state_desc = 'ONLINE' GROUP BY d.name ORDER BY d.name;
